StateEquationGenerator::Matrix StateEquationGenerator::calcMatrix(
  const std::vector<ReferencePoint> & ref_points) const
{
  autoware_utils::ScopedTimeTrack st(__func__, *time_keeper_);

  const size_t D_x = vehicle_model_ptr_->getDimX();
  const size_t D_u = vehicle_model_ptr_->getDimU();

  const size_t N_ref = ref_points.size();
  const size_t N_x = N_ref * D_x;
  const size_t N_u = (N_ref - 1) * D_u;

  // matrices for whole state equation
  Eigen::MatrixXd A = Eigen::MatrixXd::Zero(N_x, N_x);
  Eigen::MatrixXd B = Eigen::MatrixXd::Zero(N_x, N_u);
  Eigen::VectorXd W = Eigen::VectorXd::Zero(N_x);

  // matrices for one-step state equation
  Eigen::MatrixXd Ad(D_x, D_x);
  Eigen::MatrixXd Bd(D_x, D_u);
  Eigen::MatrixXd Wd(D_x, 1);

  A.block(0, 0, D_x, D_x) = Eigen::MatrixXd::Identity(D_x, D_x);

  // calculate one-step state equation considering kinematics N_ref times
  for (size_t i = 1; i < N_ref; ++i) {
    // get discrete kinematics matrix A, B, W
    const auto & p = ref_points.at(i - 1);

    // TODO(murooka) use curvature by stabling optimization
    // Currently, when using curvature, the optimization result is weird with sample_map.
    // vehicle_model_ptr_->calculateStateEquationMatrix(Ad, Bd, Wd, p.curvature,
    // p.delta_arc_length);
    vehicle_model_ptr_->calculateStateEquationMatrix(Ad, Bd, Wd, 0.0, p.delta_arc_length);

    A.block(i * D_x, (i - 1) * D_x, D_x, D_x) = Ad;
    B.block(i * D_x, (i - 1) * D_u, D_x, D_u) = Bd;
    W.segment(i * D_x, D_x) = Wd;
  }

  return Matrix{A, B, W};
}

int VehicleModelInterface::getDimX() const
{
  return dim_x_;
}

int VehicleModelInterface::getDimU() const
{
  return dim_u_;
}

void KinematicsBicycleModel::calculateStateEquationMatrix(
  Eigen::MatrixXd & Ad, Eigen::MatrixXd & Bd, Eigen::MatrixXd & Wd, const double curvature,
  const double ds) const
{
  const double delta_r = std::atan(wheelbase_ * curvature);
  const double cropped_delta_r = std::clamp(delta_r, -steer_limit_, steer_limit_);

  // NOTE: cos(delta_r) will not be zero since curvature will not be infinity
  Ad << 1.0, ds, 0.0, 1.0;

  Bd << 0.0, ds / wheelbase_ / std::pow(std::cos(delta_r), 2.0);

  Wd << 0.0, -ds * curvature + ds / wheelbase_ *
                                 (std::tan(cropped_delta_r) -
                                  cropped_delta_r / std::pow(std::cos(cropped_delta_r), 2.0));
}

MPTOptimizer::ObjectiveMatrix MPTOptimizer::calcObjectiveMatrix(
  [[maybe_unused]] const StateEquationGenerator::Matrix & mpt_mat, const ValueMatrix & val_mat,
  const std::vector<ReferencePoint> & ref_points) const
{
  autoware_utils::ScopedTimeTrack st(__func__, *time_keeper_);

  const size_t D_x = state_equation_generator_.getDimX();
  const size_t D_u = state_equation_generator_.getDimU();

  const size_t N_ref = ref_points.size();
  const size_t N_slack = getNumberOfSlackVariables();

  const size_t N_x = N_ref * D_x;
  const size_t N_u = (N_ref - 1) * D_u;
  const size_t N_s = N_ref * N_slack;

  const size_t N_v = N_x + N_u + N_s;

  // generate T matrix and vector to shift optimization center
  // NOTE: Z is defined as time-series vector of shifted deviation
  //       error where Z = sparse_T_mat * X + T_vec
  time_keeper_->start_track("objectiveMatrix_Tmatrix");
  std::vector<Eigen::Triplet<double>> triplet_T_vec;
  Eigen::VectorXd T_vec = Eigen::VectorXd::Zero(N_x);
  const double offset = mpt_param_.optimization_center_offset;
  for (size_t i = 0; i < N_ref; ++i) {
    const double alpha = ref_points.at(i).alpha;

    triplet_T_vec.push_back(Eigen::Triplet<double>(i * D_x, i * D_x, std::cos(alpha)));
    triplet_T_vec.push_back(Eigen::Triplet<double>(i * D_x, i * D_x + 1, offset * std::cos(alpha)));
    triplet_T_vec.push_back(Eigen::Triplet<double>(i * D_x + 1, i * D_x + 1, 1.0));

    T_vec(i * D_x) = -offset * std::sin(alpha);
  }
  Eigen::SparseMatrix<double> sparse_T_mat(N_x, N_x);
  sparse_T_mat.setFromTriplets(triplet_T_vec.begin(), triplet_T_vec.end());
  time_keeper_->end_track("objectiveMatrix_Tmatrix");

  // NOTE: min J(v) = min (v'Hv + v'g)
  time_keeper_->start_track("objectiveMatrix_Hx");
  Eigen::MatrixXd H_x = Eigen::MatrixXd::Zero(N_x, N_x);
  H_x.triangularView<Eigen::Upper>() =
    Eigen::MatrixXd(sparse_T_mat.transpose() * val_mat.Q * sparse_T_mat);
  H_x.triangularView<Eigen::Lower>() = H_x.transpose();
  time_keeper_->end_track("objectiveMatrix_Hx");

  time_keeper_->start_track("objectiveMatrix_Hg");
  Eigen::MatrixXd H = Eigen::MatrixXd::Zero(N_v, N_v);
  H.block(0, 0, N_x, N_x) = H_x;
  H.block(N_x, N_x, N_u, N_u) = val_mat.R;

  Eigen::VectorXd g = Eigen::VectorXd::Zero(N_v);
  g.segment(0, N_x) = T_vec.transpose() * val_mat.Q * sparse_T_mat;
  g.segment(N_x + N_u, N_s) = mpt_param_.soft_collision_free_weight * Eigen::VectorXd::Ones(N_s);
  time_keeper_->end_track("objectiveMatrix_Hg");

  time_keeper_->comment(
    "N_ref=" + std::to_string(N_ref) + ", N_x=" + std::to_string(N_x) + ", N_u=" +
    std::to_string(N_u) + ", N_s=" + std::to_string(N_s) + ", N_v=" + std::to_string(N_v) +
    ", H=" + std::to_string(N_v) + "x" + std::to_string(N_v) + ", g=" + std::to_string(N_v));

  ObjectiveMatrix obj_matrix;
  obj_matrix.hessian = H;
  obj_matrix.gradient = g;

  return obj_matrix;
}

size_t MPTOptimizer::getNumberOfSlackVariables() const
{
  if (mpt_param_.soft_constraint) {
    if (mpt_param_.l_inf_norm) {
      return 1;
    }
    return vehicle_circle_longitudinal_offsets_.size();
  }
  return 0;
}

