AcadosSolution MPTOptimizer::runAcadosMPT(
  const std::vector<ReferencePoint> & ref_points,
  autoware::interpolation::SplineInterpolationPoints2d & ref_points_spline,
  const geometry_msgs::msg::Pose & ego_pose)
{
  // Get spline coefficients for curvature only
  const auto & knots = ref_points_spline.getSplineKnots();
  const auto & curvatures = ref_points_spline.getSplineInterpolatedCurvatures();

  const auto [s_ego, e_y_ego] =
    ref_points_spline.projectPointOntoSpline(ego_pose.position.x, ego_pose.position.y);

  const double ego_yaw = tf2::getYaw(ego_pose.orientation);
  const double ref_yaw = ref_points_spline.getSplineInterpolatedYaw(0, s_ego);
  const double e_psi_ego = ego_yaw - ref_yaw;

  // Convert arrays to vectors for buildParameters
  std::vector<double> knots_vec(knots.begin(), knots.end());
  std::vector<double> curvatures_vec(curvatures.begin(), curvatures.end());

  size_t n_segments = knots.size() - 1;

  size_t target_n_knots = CURVILINEAR_BICYCLE_MODEL_SPATIAL_N;
  size_t target_segments = target_n_knots - 1;

  // Adjust sizes if necessary (simple strategy: extend last values)
  if (n_segments < target_segments) {
    ref_points_spline.extendLinearlyForward(target_n_knots, mpt_param_.delta_arc_length);

    const auto & knots_new = ref_points_spline.getSplineKnots();
    const auto & curvatures_new = ref_points_spline.getSplineInterpolatedCurvatures();
    knots_vec.assign(knots_new.begin(), knots_new.end());
    curvatures_vec.assign(curvatures_new.begin(), curvatures_new.end());
  } else if (n_segments > target_segments) {
    ref_points_spline.resize(target_n_knots);

    const auto & knots_new = ref_points_spline.getSplineKnots();
    const auto & curvatures_new = ref_points_spline.getSplineInterpolatedCurvatures();

    knots_vec.assign(knots_new.begin(), knots_new.end());
    curvatures_vec.assign(curvatures_new.begin(), curvatures_new.end());
  }

  std::array<double, NX> x0;
  x0[0] = e_y_ego;
  x0[1] = e_psi_ego;

  std::array<double, NP> parameters = buildParameters(knots_vec, curvatures_vec);

  setParametersToSolver(parameters, ref_points, s_ego);

  AcadosSolution acados_solution = acados_interface_.getControl(x0);

  return acados_solution;
}

std::pair<double, double> SplineInterpolationPoints2d::projectPointOntoSpline(
  const double x_i, const double y_i, double s_init, const double tol, const int max_iter) const
{
  double s = s_init;

  // Coarse search: iterate over spline knots to find closest s
  const auto & knots = spline_x_.getKnots();
  double min_dist = std::numeric_limits<double>::max();
  for (const auto & s_knot : knots) {
    double dx = spline_x_.getSplineInterpolatedValues({s_knot}).at(0) - x_i;
    double dy = spline_y_.getSplineInterpolatedValues({s_knot}).at(0) - y_i;
    double dist = std::hypot(dx, dy);
    if (dist < min_dist) {
      min_dist = dist;
      s = s_knot;
    }
  }

  // Newton iteration with proper second derivative
  for (int iter = 0; iter < max_iter; ++iter) {
    const double x_s = spline_x_.getSplineInterpolatedValues({s}).at(0);
    const double y_s = spline_y_.getSplineInterpolatedValues({s}).at(0);

    const double dx_ds = spline_x_.getSplineInterpolatedDiffValues({s}).at(0);
    const double dy_ds = spline_y_.getSplineInterpolatedDiffValues({s}).at(0);

    const double d2x_ds2 = spline_x_.getSplineInterpolatedQuadDiffValues({s}).at(0);
    const double d2y_ds2 = spline_y_.getSplineInterpolatedQuadDiffValues({s}).at(0);

    // f'(s) = d/ds[||p(s) - p_i||^2] = 2[(x_s - x_i)·dx_ds + (y_s - y_i)·dy_ds]
    const double df_ds = (x_s - x_i) * dx_ds + (y_s - y_i) * dy_ds;

    // f''(s) = d²/ds²[||p(s) - p_i||^2] = 2[dx_ds² + dy_ds² + (x_s - x_i)·d²x_ds² + (y_s -
    // y_i)·d²y_ds²]
    const double d2f_ds2 =
      dx_ds * dx_ds + dy_ds * dy_ds + (x_s - x_i) * d2x_ds2 + (y_s - y_i) * d2y_ds2;

    if (std::fabs(d2f_ds2) < 1e-12) break;  // avoid divide by zero

    double ds = df_ds / d2f_ds2;

    // Bind s between min s and max s
    if (s - ds < base_s_vec_.front()) {
      ds = s - base_s_vec_.front();
    } else if (s - ds > base_s_vec_.back()) {
      ds = s - base_s_vec_.back();
    }
    s -= ds;

    if (std::fabs(ds) < tol) {
      break;  // converged
    }
  }

  // Compute cross-track error eY
  double x_s = spline_x_.getSplineInterpolatedValues({s}).at(0);
  double y_s = spline_y_.getSplineInterpolatedValues({s}).at(0);
  double psi_s = getSplineInterpolatedYaw(0, s);

  double eY = -(x_i - x_s) * std::sin(psi_s) + (y_i - y_s) * std::cos(psi_s);

  return {s, eY};
}

std::vector<double> SplineInterpolation::getSplineInterpolatedValues(
  const std::vector<double> & query_keys) const
{
  // throw exceptions for invalid arguments
  const auto validated_query_keys = autoware::interpolation::validateKeys(base_keys_, query_keys);
  std::vector<double> interpolated_values;
  interpolated_values.reserve(query_keys.size());

  for (const auto & key : query_keys) {
    const auto idx = get_index(key);
    const auto dx = key - base_keys_[idx];
    interpolated_values.emplace_back(
      a_[idx] * dx * dx * dx + b_[idx] * dx * dx + c_[idx] * dx + d_[idx]);
  }

  return interpolated_values;
}

inline std::vector<double> validateKeys(
  const std::vector<double> & base_keys, const std::vector<double> & query_keys)
{
  // when vectors are empty
  if (base_keys.empty() || query_keys.empty()) {
    throw std::invalid_argument("Points is empty.");
  }

  // when size of vectors are less than 2
  if (base_keys.size() < 2) {
    throw std::invalid_argument(
      "The size of points is less than 2. base_keys.size() = " + std::to_string(base_keys.size()));
  }

  // when indices are not sorted
  if (!isIncreasing(base_keys) || !isNotDecreasing(query_keys)) {
    throw std::invalid_argument("Either base_keys or query_keys is not sorted.");
  }

  // when query_keys is out of base_keys (This function does not allow exterior division.)
  constexpr double epsilon = 1e-3;
  if (
    query_keys.front() < base_keys.front() - epsilon ||
    base_keys.back() + epsilon < query_keys.back()) {
    throw std::invalid_argument("query_keys is out of base_keys");
  }

  // NOTE: Due to calculation error of double, a query key may be slightly out of base keys.
  //       Therefore, query keys are cropped here.
  auto validated_query_keys = query_keys;
  validated_query_keys.front() = std::max(validated_query_keys.front(), base_keys.front());
  validated_query_keys.back() = std::min(validated_query_keys.back(), base_keys.back());

  return validated_query_keys;
}

inline bool isIncreasing(const std::vector<double> & x)
{
  if (x.empty()) {
    throw std::invalid_argument("Points is empty.");
  }

  for (size_t i = 0; i < x.size() - 1; ++i) {
    if (x.at(i) >= x.at(i + 1)) {
      return false;
    }
  }

  return true;
}

Eigen::Index SplineInterpolation::get_index(const double & key) const
{
  const auto it = std::lower_bound(base_keys_.begin(), base_keys_.end(), key);
  return std::clamp(
    static_cast<int>(std::distance(base_keys_.begin(), it)) - 1, 0,
    static_cast<int>(base_keys_.size()) - 2);
}

std::vector<double> SplineInterpolation::getSplineInterpolatedDiffValues(
  const std::vector<double> & query_keys) const
{
  // throw exceptions for invalid arguments
  const auto validated_query_keys = autoware::interpolation::validateKeys(base_keys_, query_keys);
  std::vector<double> interpolated_diff_values;
  interpolated_diff_values.reserve(query_keys.size());

  for (const auto & key : query_keys) {
    const auto idx = get_index(key);
    const auto dx = key - base_keys_[idx];
    interpolated_diff_values.emplace_back(3 * a_[idx] * dx * dx + 2 * b_[idx] * dx + c_[idx]);
  }

  return interpolated_diff_values;
}

inline std::vector<double> validateKeys(
  const std::vector<double> & base_keys, const std::vector<double> & query_keys)
{
  // when vectors are empty
  if (base_keys.empty() || query_keys.empty()) {
    throw std::invalid_argument("Points is empty.");
  }

  // when size of vectors are less than 2
  if (base_keys.size() < 2) {
    throw std::invalid_argument(
      "The size of points is less than 2. base_keys.size() = " + std::to_string(base_keys.size()));
  }

  // when indices are not sorted
  if (!isIncreasing(base_keys) || !isNotDecreasing(query_keys)) {
    throw std::invalid_argument("Either base_keys or query_keys is not sorted.");
  }

  // when query_keys is out of base_keys (This function does not allow exterior division.)
  constexpr double epsilon = 1e-3;
  if (
    query_keys.front() < base_keys.front() - epsilon ||
    base_keys.back() + epsilon < query_keys.back()) {
    throw std::invalid_argument("query_keys is out of base_keys");
  }

