std::array<double, NP> MPTOptimizer::buildParameters(
  const std::vector<double> & knots, const std::vector<double> & curvatures) const
{
  RCLCPP_DEBUG(logger_, "sizes: knots=%zu curvatures=%zu", knots.size(), curvatures.size());

  // Build parameters vector similar to Python
  std::array<double, NP> parameters;
  parameters.fill(0.0);
  double s_interp = 0.0;
  size_t idx = 0;

  // 1. s_interp
  parameters[idx++] = s_interp;

  // 2. knots
  for (double v : knots) {
    parameters[idx++] = v;
  }

  // 3. Compute cubic spline coefficients from curvatures
  // Fit a cubic spline to (knots, curvatures) and extract the 4×(N-1) coefficients

  autoware::interpolation::SplineInterpolation spline(knots, curvatures);
  const Eigen::VectorXd coeffs_eigen = spline.getCoefficients();
  const std::vector<double> clothoid_coeffs_flat(
    coeffs_eigen.data(), coeffs_eigen.data() + coeffs_eigen.size());

  for (double v : clothoid_coeffs_flat) {
    parameters[idx++] = v;
  }

  const double lf = vehicle_info_.wheel_base_m;

  parameters[idx++] = lf;
  parameters[idx++] = 0.0;

  // Ensure the circle-constraint tail of p is filled deterministically.
  // Layout: [... base ... | cos_beta[0..NH-1] | sin_beta[0..NH-1] | lon_offset[0..NH-1]]
  const size_t cos_beta_offset = NP - 3 * NH;
  const size_t sin_beta_offset = NP - 2 * NH;
  const size_t lon_offset_offset = NP - 1 * NH;
  for (size_t i = 0; i < NH; ++i) {
    parameters[cos_beta_offset + i] = 1.0;
    parameters[sin_beta_offset + i] = 0.0;
    parameters[lon_offset_offset + i] = (i < vehicle_circle_longitudinal_offsets_.size())
                                          ? vehicle_circle_longitudinal_offsets_.at(i)
                                          : 0.0;
  }

  return parameters;
}

AcadosSolution AcadosInterface::getControl(std::array<double, NX> x0)
{
  // initial value for control input
  std::array<double, NU> u0;
  u0.fill(0.0);

  // prepare evaluation
  double kkt_norm_inf;
  double elapsed_time;
  int sqp_iter;

  // initialize solution
  setInitialState(x0);

  int status = curvilinear_bicycle_model_spatial_acados_solve(capsule_);
  ocp_nlp_get(nlp_solver_, "time_tot", &elapsed_time);

  ocp_nlp_out_get(nlp_config_, nlp_dims_, nlp_out_, 0, "kkt_norm_inf", &kkt_norm_inf);
  ocp_nlp_get(nlp_solver_, "sqp_iter", &sqp_iter);

  curvilinear_bicycle_model_spatial_acados_print_stats(capsule_);

  std::stringstream ss;
  ss << "\nSolver info:" << std::endl;
  ss << " SQP iterations " << sqp_iter << "\n minimum time for " << 1 << " solve "
     << elapsed_time * 1000 << " [ms]\n KKT " << kkt_norm_inf << std::endl;

  AcadosSolution solution;

  solution.xtraj = getStateTrajectory();
  solution.utraj = getControlTrajectory();

  solution.sqp_iter = sqp_iter;
  solution.kkt_norm_inf = kkt_norm_inf;
  solution.elapsed_time = elapsed_time;

  solution.status = status;
  solution.info = ss.str();

  return solution;
}

void AcadosInterface::setInitialState(std::array<double, NX> x0)
{
  // set both lbx and ubx at stage 0 to force initial state
  ocp_nlp_constraints_model_set(
    nlp_config_, nlp_dims_, nlp_in_, nlp_out_, 0, "lbx", const_cast<double *>(x0.data()));
  ocp_nlp_constraints_model_set(
    nlp_config_, nlp_dims_, nlp_in_, nlp_out_, 0, "ubx", const_cast<double *>(x0.data()));
  // Do not seed the full trajectory in ocp_nlp_out here; Python only sets lbx/ubx at stage 0.
}

